import 'package:flutter/material.dart';
import '../../services/api_service.dart';

class SupervisorsScreen extends StatefulWidget { const SupervisorsScreen({super.key}); @override State<SupervisorsScreen> createState()=>_SupervisorsScreenState(); }
class _SupervisorsScreenState extends State<SupervisorsScreen>{
 List supervisors=[];bool loading=true;
 List<dynamic> list(dynamic x)=>x is List?List<dynamic>.from(x):(x is Map&&x['data'] is List?List<dynamic>.from(x['data']):[]);
 int id(dynamic x)=>int.tryParse('${x['id']}')??0;
 void msg(Object e)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.toString().replaceFirst('Exception: ',''))));
 @override void initState(){super.initState();load();}
 Future<void> load()async{try{final r=await ApiService.get('supervisors');if(mounted)setState((){supervisors=list(r);loading=false;});}catch(e){if(mounted){setState(()=>loading=false);msg(e);}}}
 Future<void> form({dynamic supervisor})async{final name=TextEditingController(text:'${supervisor?['name']??''}'),phone=TextEditingController(text:'${supervisor?['phone']??''}'),email=TextEditingController(text:'${supervisor?['email']??''}');final key=GlobalKey<FormState>();final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:Text(supervisor==null?'إضافة مشرف':'تعديل المشرف'),content:Form(key:key,child:Column(mainAxisSize:MainAxisSize.min,children:[TextFormField(controller:name,decoration:const InputDecoration(labelText:'اسم المشرف *'),validator:(v)=>v==null||v.trim().isEmpty?'مطلوب':null),TextFormField(controller:phone,decoration:const InputDecoration(labelText:'الهاتف')),TextFormField(controller:email,decoration:const InputDecoration(labelText:'البريد'))])),actions:[TextButton(onPressed:()=>Navigator.pop(dc,false),child:const Text('إلغاء')),FilledButton(onPressed:(){if(key.currentState!.validate())Navigator.pop(dc,true);},child:const Text('حفظ'))]));if(ok==true){try{final body={'name':name.text.trim(),'phone':phone.text.trim(),'email':email.text.trim()};if(supervisor==null){body['status']='active';await ApiService.post('supervisors',body);}else{await ApiService.put('supervisors/${id(supervisor)}',body);}await load();}catch(e){msg(e);}}for(final c in[name,phone,email])c.dispose();}
 Future<void> remove(dynamic s)async{final ok=await showDialog<bool>(context:context,builder:(dc)=>AlertDialog(title:const Text('حذف المشرف'),content:Text('هل تريد حذف «${s['name']??''}»؟'),actions:[TextButton(onPressed:()=>Navigator.pop(dc,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(dc,true),child:const Text('حذف'))]));if(ok==true){try{await ApiService.delete('supervisors/${id(s)}');await load();}catch(e){msg(e);}}}
 Future<void> details(int supervisorId)async{try{final r=await ApiService.get('supervisors/$supervisorId');final d=Map<String,dynamic>.from(r is Map&&r['data'] is Map?r['data']:r);if(!mounted)return;final pl=list(d['private_lessons']),gl=list(d['group_lessons']),history=list(d['lessons']);await showDialog(context:context,builder:(dc)=>AlertDialog(title:Text('${d['supervisor']?['name']??'المشرف'}'),content:SizedBox(width:520,child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('ملخص الإشراف',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),Text('خاصة: ${pl.length}'),Text('جروب: ${gl.length}'),Text('إجمالي: ${d['lessons_count']??0}'),Text('المستحق: ${d['due']??0}'),Text('المدفوع: ${d['paid']??0}'),Text('المتبقي: ${d['remaining']??0}'),Text('المكافآت: ${d['bonus_total']??0}')]))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('سجل الحصص',style:TextStyle(fontWeight:FontWeight.bold,fontSize:17)),if(history.isEmpty)const Text('لا توجد حصص.'),...history.map((x)=>ListTile(dense:true,title:Text('${x['subject']??''}'),subtitle:Text('${x['type']??''} • ${x['starts_at']??''}')))])))]))),actions:[TextButton(onPressed:()=>Navigator.pop(dc),child:const Text('إغلاق'))]));}catch(e){msg(e);}}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المشرفون'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>form(),icon:const Icon(Icons.person_add),label:const Text('إضافة مشرف')),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets.fromLTRB(16,12,16,90),children:[Card(child:Padding(padding:const EdgeInsets.all(14),child:const Text('أضف المشرف ثم اربطه بالحصة. يمكنك تعديل أو حذف المشرف من القائمة.'))),if(supervisors.isEmpty)const Padding(padding:EdgeInsets.all(30),child:Center(child:Text('لا يوجد مشرفون.'))),...supervisors.map((s)=>Card(child:ListTile(onTap:()=>details(id(s)),leading:const CircleAvatar(child:Icon(Icons.supervisor_account)),title:Text('${s['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold)),subtitle:Text('${s['lessons_count']??0} حصة'),trailing:Wrap(mainAxisSize:MainAxisSize.min,children:[IconButton(onPressed:()=>form(supervisor:s),icon:const Icon(Icons.edit)),IconButton(onPressed:()=>remove(s),icon:const Icon(Icons.delete)),const Icon(Icons.chevron_left)]))))]));
}
